#!/bin/sh
# 链接顺序敏感性：被依赖的库必须靠后
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > math.c << 'EOF'
int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.c << 'EOF'
int add(int, int);

int twice(int x)      /* util 依赖 math 里的 add */
{
    return add(x, x);
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int twice(int);

int main(void)
{
    printf("twice(21) = %d\n", twice(21));
    return 0;
}
EOF

gcc -c math.c -o math.o
ar rcs libmath.a math.o
gcc -c util.c -o util.o
ar rcs libutil.a util.o
gcc -c main.c -o main.o
gcc main.o -L. -lmath -lutil -o app_bad   # 错误顺序：被依赖者在前
gcc main.o -L. -lutil -lmath -o app_ok    # 正确顺序：调用者在前
./app_ok
